//! Native HTMLLabelElement.control reads actual associated elements.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><label id=label for=seed>Choice</label><input id=field type=checkbox><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://label-for-accessor.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn html_label_control_explicit_exact_first_match_and_implicit_tree_order(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var label=document.getElementById('label'),field=document.getElementById('field');label.htmlFor='field';if(label.control!==field)throw 'actual explicit control';var a=document.createElement('input'),literal=document.createElement('input');a.id='A\ud800z';literal.id='A�z';document.getElementById('mount').appendChild(a);document.getElementById('mount').appendChild(literal);label.htmlFor='A\ud800z';if(label.control!==a||label.control===literal)throw 'exact native associated control';var blocker=document.createElement('div');blocker.id='A\ud800z';document.getElementById('mount').insertBefore(blocker,a);if(label.control!==null)throw 'first nonlabelable ID match blocks later control';blocker.remove();if(label.control!==a)throw 'live first match recovery';label.removeAttribute('for');var hidden=document.createElement('input'),nested=document.createElement('span'),choice=document.createElement('input');hidden.setAttribute('type','hidden');nested.appendChild(choice);label.appendChild(hidden);label.appendChild(nested);if(label.control!==choice)throw 'implicit first labelable descendant';label.htmlFor='';if(label.control!==null)throw 'present empty for excludes implicit association';"#);}
#[test]
fn html_label_control_inert_detached_root_and_all_builtin_labelable_elements(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),root=owner.createElementNS('http://www.w3.org/1999/xhtml','div'),label=owner.createElementNS('http://www.w3.org/1999/xhtml','label');root.appendChild(label);for(var name of ['button','input','meter','output','progress','select','textarea']){var element=owner.createElementNS('http://www.w3.org/1999/xhtml',name);element.id='A\ud800z';root.appendChild(element);label.htmlFor='A\ud800z';if(label.control!==element)throw 'actual detached labelable '+name;root.removeChild(element);}label.removeAttribute('for');var foreign=owner.createElementNS('urn:foreign','input'),input=owner.createElementNS('http://www.w3.org/1999/xhtml','input');label.appendChild(foreign);label.appendChild(input);if(label.control!==input)throw 'namespace-qualified implicit labelable control';label.htmlFor='field';if(label.control!==null)throw 'separate root excludes main document control';"#);}
#[test]
fn html_label_control_canonical_readonly_descriptor_and_genuine_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'control'),label=document.getElementById('label');if(!descriptor||typeof descriptor.get!=='function'||descriptor.set!==undefined||!descriptor.enumerable||!descriptor.configurable||descriptor.get.name!=='get control'||descriptor.get.length!==0||Object.hasOwn(label,'control'))throw 'canonical readonly descriptor';label.htmlFor='field';if(descriptor.get.call(label)!==document.getElementById('field'))throw 'saved native getter';for(var bad of [{},Object.create(HTMLLabelElement.prototype),document,document.createElement('div'),document.createElementNS('urn:foreign','label')]){var caught=false;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine label brand';}label.control='ignored';if(label.control!==document.getElementById('field'))throw 'sloppy readonly';var caught=false;try{(function(){'use strict';label.control=null;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'strict readonly';"#);}

#[test]
fn html_label_control_live_type_ids_namespace_and_author_overrides(){let(mut d,mut f,mut p)=fixture();let before=format!("{:?}",d.nodes);let error=p.runtime.execute("document.getElementById('field').setAttribute('type','hidden');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("input type"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);p.begin_job();run(&mut d,&mut f,&mut p,r#"var label=document.getElementById('label'),field=document.getElementById('field'),descriptor=Object.getOwnPropertyDescriptor(HTMLLabelElement.prototype,'control');label.htmlFor='field';var owner=document.implementation.createHTMLDocument('types'),box=owner.createElement('label'),typed=owner.createElement('input');box.appendChild(typed);typed.setAttribute('type','HiDdEn');if(box.control!==null)throw 'hidden input state';typed.setAttribute('type','unknown');if(box.control!==typed)throw 'unknown input state text';field.id='fresh';if(label.control!==null)throw 'live native id';label.getAttributeNode('for').value='fresh';if(label.control!==field)throw 'live attached attribute';label.setAttributeNS('urn:attribute','for','absent');if(label.control!==field)throw 'qualified for has no authority';var calls=0;Object.defineProperty(field,'id',{get:function(){calls++;return 'absent';},configurable:true});Object.defineProperty(label,'htmlFor',{get:function(){calls++;return 'absent';},configurable:true});if(label.control!==field||calls)throw 'native association ignores author projections';Object.defineProperty(label,'control',{get:function(){return 'own';},configurable:true});if(label.control!=='own'||descriptor.get.call(label)!==field)throw 'own getter separated from native association';delete label.control;Object.defineProperty(HTMLLabelElement.prototype,'control',{value:'prototype',configurable:true});if(label.control!=='prototype'||descriptor.get.call(label)!==field)throw 'prototype override';delete HTMLLabelElement.prototype.control;if(label.control!==undefined||descriptor.get.call(label)!==field)throw 'deleted native descriptor';Object.defineProperty(HTMLLabelElement.prototype,'control',descriptor);var count=0;for(var key in label)if(key==='control')count++;if(count!==1||Object.hasOwn(label,'control')||label.control!==field)throw 'restored inherited enumerable accessor';"#);}
#[test]
fn html_label_control_native_clone_import_template_and_adopted_roots(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),group=owner.createElement('div'),label=owner.createElement('label'),field=owner.createElement('input');label.htmlFor='A\ud800z';field.id='A\ud800z';group.appendChild(label);group.appendChild(field);owner.body.appendChild(group);var clone=group.cloneNode(true),copy=document.importNode(group,true);if(label.control!==field||clone.firstChild.control!==clone.lastChild||copy.firstChild.control!==copy.lastChild||copy.firstChild.control===field)throw 'independent native snapshot roots';document.getElementById('mount').appendChild(copy);if(copy.firstChild.control!==copy.lastChild||label.control!==field)throw 'actual imported owner association';var target=document.implementation.createHTMLDocument('target');target.adoptNode(group);if(label.ownerDocument!==target||label.control!==field)throw 'adopted disconnected actual root';group.removeChild(field);if(label.control!==null)throw 'removed adopted target';group.appendChild(field);if(label.control!==field)throw 'adopted recovery';var t=document.createElement('template');t.innerHTML='<label for=parked></label><input id=parked>';var parked=t.content.firstChild,actual=t.content.lastChild;var content=t.content;if(parked.control!==actual)throw 'actual template content root';if(t.content!==content||!content||content.nodeType!==11)throw 'template content identity after native getter';"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let error=p.runtime.execute("document.getElementById('mount').appendChild(content);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("DOM node")||error.contains("supported"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,r#"if(parked.control!==actual||t.content!==content)throw 'native control template refusal preserves association';t.innerHTML='<label for=field></label>';parked=t.content.firstChild;if(parked.control!==null)throw 'template content root excludes main control';document.getElementById('mount').appendChild(t.content);if(parked.control!==document.getElementById('field')||parked.ownerDocument!==document)throw 'promoted label identity association';"#);}
#[test]
fn html_label_control_read_limits_and_cancellation_preserve_native_state(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var label=document.getElementById('label');label.htmlFor='field';");let label=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("label")).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let retained=p.state.retained_limit;for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_label_control_get(node_handle(label)).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.retained_limit=retained;p.state.execution_deadline=None;}p.begin_job();run(&mut d,&mut f,&mut p,"if(label.control!==document.getElementById('field'))throw 'fresh native read recovery';");}
#[test]
fn html_label_control_saved_child_origin_checks_and_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('label'),frame=document.createElement('iframe');source.htmlFor='field';frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLLabelElement.prototype,'control');if(descriptor.get.call(source)!==document.getElementById('field'))throw 'same origin saved getter';");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-label-control.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("descriptor.get.call(source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://label-for-accessor.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(descriptor.get.call(source)!==document.getElementById('field'))throw 'fresh origin recovery';");}
#[test]
fn html_label_control_no_main_slot_foreign_id_blocker_and_empty_id(){let(mut d,mut f,mut p)=fixture();let count=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=count;run(&mut d,&mut f,&mut p,r#"var owner=new Document(),root=owner.createElementNS('http://www.w3.org/1999/xhtml','div'),label=owner.createElementNS('http://www.w3.org/1999/xhtml','label'),input=owner.createElementNS('http://www.w3.org/1999/xhtml','input'),foreign=owner.createElementNS('urn:foreign','input');root.appendChild(label);root.appendChild(foreign);root.appendChild(input);foreign.setAttribute('id','field');input.id='field';label.htmlFor='field';if(label.control!==null)throw 'foreign first id blocks HTML input';root.removeChild(foreign);if(label.control!==input)throw 'live exact root recovery';input.id='';label.htmlFor='';if(label.control!==null)throw 'empty id has no identity';label.removeAttribute('for');label.appendChild(input);if(label.control!==input)throw 'no main slot implicit association';"#);assert_eq!(d.nodes.len(),count);p.state.node_limit=limit;}
